import { chromium } from 'playwright';

const browser = await chromium.launch();

async function measure(storyId, label) {
  const page = await browser.newPage({ viewport: { width: 400, height: 300 } });
  await page.goto(`http://localhost:6006/iframe.html?id=${storyId}&viewMode=story`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(1500);

  const buttons = await page.locator('button').all();
  const buttonInfo = [];
  for (const btn of buttons) {
    const box = await btn.boundingBox();
    const cs = await btn.evaluate((el) => {
      const s = getComputedStyle(el);
      return { opacity: s.opacity, cursor: s.cursor, ariaDisabled: el.getAttribute('aria-disabled') };
    });
    const svgPath = await btn.locator('svg path, svg').first().evaluate((el) => el.outerHTML).catch(() => null);
    buttonInfo.push({ label: await btn.getAttribute('aria-label'), box, ...cs, svg: svgPath?.slice(0, 120) });
  }

  const valueSpan = page.locator('span[aria-live="polite"]');
  const valueBox = await valueSpan.boundingBox();
  const valueCs = await valueSpan.evaluate((el) => {
    const s = getComputedStyle(el);
    return { fontSize: s.fontSize, fontWeight: s.fontWeight, lineHeight: s.lineHeight, opacity: s.opacity, text: el.textContent };
  });

  const root = valueSpan.locator('xpath=..');
  const rootCs = await root.evaluate((el) => getComputedStyle(el).gap);

  // focus test: tab to first button, measure outline/boxShadow before and after
  const firstBtn = buttons[0];
  const beforeFocus = await firstBtn.evaluate((el) => {
    const s = getComputedStyle(el);
    return { outline: s.outline, boxShadow: s.boxShadow };
  });
  await firstBtn.focus();
  await page.waitForTimeout(200);
  const afterFocus = await firstBtn.evaluate((el) => {
    const s = getComputedStyle(el);
    return { outline: s.outline, boxShadow: s.boxShadow };
  });

  console.log(`\n=== ${label} (${storyId}) ===`);
  console.log('root gap:', rootCs);
  console.log('buttons:', JSON.stringify(buttonInfo, null, 2));
  console.log('value:', JSON.stringify({ box: valueBox, ...valueCs }));
  console.log('focus before:', JSON.stringify(beforeFocus), 'after:', JSON.stringify(afterFocus));
  if (buttonInfo.length === 2) {
    const gapPx = buttonInfo[1].box.x - (buttonInfo[0].box.x + buttonInfo[0].box.width);
    const edgeToEdge = buttonInfo[1].box.x - (buttonInfo[0].box.x + buttonInfo[0].box.width);
    console.log('measured left-button-right-edge to value-left-edge:', valueBox.x - (buttonInfo[0].box.x + buttonInfo[0].box.width));
    console.log('measured value-right-edge to right-button-left-edge:', buttonInfo[1].box.x - (valueBox.x + valueBox.width));
  }

  await page.close();
}

await measure('commerce-zimmquantitystepper--default', 'Default');
await measure('commerce-zimmquantitystepper--at-minimum', 'At Minimum');
await measure('commerce-zimmquantitystepper--at-maximum', 'At Maximum');
await measure('commerce-zimmquantitystepper--unavailable', 'Unavailable');

await browser.close();

