import { chromium } from 'playwright';

const browser = await chromium.launch();
const context = await browser.newContext();
const page = await context.newPage({ viewport: { width: 400, height: 300 } });
await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmquantitystepper--at-minimum&viewMode=story', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);

const decBtn = page.getByRole('button', { name: 'Decrease quantity' });
const incBtn = page.getByRole('button', { name: 'Increase quantity' });
const value = page.locator('span[aria-live="polite"]');

console.log('value text (fresh context):', await value.textContent());
console.log('decrement aria-disabled:', await decBtn.getAttribute('aria-disabled'));
console.log('decrement opacity:', await decBtn.evaluate((el) => getComputedStyle(el).opacity));
console.log('decrement cursor:', await decBtn.evaluate((el) => getComputedStyle(el).cursor));
console.log('increment aria-disabled:', await incBtn.getAttribute('aria-disabled'));

// Real keyboard tab navigation, not .focus()
await page.keyboard.press('Tab');
const afterTab1 = await page.evaluate(() => {
  const el = document.activeElement;
  const s = getComputedStyle(el);
  return { tag: el.tagName, label: el.getAttribute('aria-label'), outline: s.outline, boxShadow: s.boxShadow };
});
console.log('after 1st Tab, active element:', JSON.stringify(afterTab1));

await page.keyboard.press('Tab');
const afterTab2 = await page.evaluate(() => {
  const el = document.activeElement;
  const s = getComputedStyle(el);
  return { tag: el.tagName, label: el.getAttribute('aria-label'), outline: s.outline, boxShadow: s.boxShadow };
});
console.log('after 2nd Tab, active element:', JSON.stringify(afterTab2));

// unfocused baseline for comparison - blur and re-measure the same button
await page.evaluate(() => document.activeElement.blur());
const decBox = await decBtn.boundingBox();
const unfocused = await decBtn.evaluate((el) => {
  const s = getComputedStyle(el);
  return { outline: s.outline, boxShadow: s.boxShadow };
});
console.log('decrement button unfocused baseline:', JSON.stringify(unfocused), 'box:', JSON.stringify(decBox));

await browser.close();

